objects.ses:
on open {
  if flag(escrivaninha_aberta) { say "Já está aberta. Só papéis de contas lá dentro." }
  else { set escrivaninha_aberta; show "chave de latão"; play "tampa de madeira de escrivaninha rolando e abrindo"; say "A tampa corre com um ruído seco. Entre contas de luz, uma pequena chave de latão." }
}

on examine {
  say "O pêndulo vai e vem, tique, taque. Alguém continua dando corda nele. Os ponteiros marcam a hora certa, mas o calendário da parede parou há três semanas."
}

on take {
  set tapete_enrolado; link baixo to Porão; link cima to "Escritório de Tomás" in Porão
  hide self; take "tapete persa"
  play "tapete pesado sendo enrolado e arrastado sobre assoalho de madeira"
  say "Você enrola o tapete e o põe no ombro. É pesado, mas é um belo tapete persa: alguém, em algum lugar, pagaria bem por ele. No assoalho, onde ele estava, aparece a tampa de um alçapão com uma argola de ferro. Você a levanta: uma escada de madeira desce para o escuro."
}
on pull {
  set tapete_enrolado; link baixo to Porão; link cima to "Escritório de Tomás" in Porão
  hide self; take "tapete persa"
  play "tapete pesado sendo enrolado e arrastado sobre assoalho de madeira"
  say "Você enrola o tapete e o põe no ombro. É pesado, mas é um belo tapete persa: alguém, em algum lugar, pagaria bem por ele. No assoalho, onde ele estava, aparece a tampa de um alçapão com uma argola de ferro. Você a levanta: uma escada de madeira desce para o escuro."
}

on use {
  if here("Capitão Rocha") {
    set troca_feita; remove "tapete persa"; take "chave de ferro"; take facão; take "luvas de couro"
    play "tapete pesado desenrolado sobre balcão de madeira e moedas tilintando"
    say "Rocha desenrola o tapete sobre o balcão e passa a mão nas franjas de seda, devagar. 'Persa. De verdade.' Ele tira do cinto uma chave de ferro e, de baixo do balcão, um facão e um par de luvas grossas de couro. 'A chave abre o depósito. O facão e as luvas, você vai precisar: a selva daqui não deixa ninguém passar de mãos limpas. Calce as luvas antes de enfiar a mão onde não enxerga.'"
  }
  else { say "Trocar com quem? Não há ninguém aqui interessado num tapete." }
}

scene_54fc0d3c.ses:
on first_enter {
  say "Lúcia Albuquerque deixou a chave com você: 'Meu irmão sumiu há três semanas. A polícia desistiu. Eu não.'"
}
on enter {
  if flag(tomas_resgatado) {
    play "porta abrindo, passos apressados e choro de alegria"
    end "Vocês sobem pela escada do alçapão, cobertos de areia e sal. Lúcia está no escritório, sentada na cadeira do irmão. Ela levanta devagar, como quem não acredita, e corre para abraçá-lo. Tomás voltou para casa."
  }
}

objects.ses:
on open {
  if flag(bau_aberto) { say "Já está aberto." }
  else { say "Trancado. A fechadura é pequena, de latão." }
}
on use with "chave de latão" {
  if flag(bau_aberto) { say "Já está aberto." }
  else {
    set bau_aberto; show "cartão perfurado"; show "carta das marés"; show lanterna; show "caixa de bijuterias"
    play "fechadura de latão girando e tampa de baú de madeira rangendo"
    say "A chave gira e a tampa range ao subir. Dentro do baú: um cartão perfurado, uma carta náutica dobrada, uma lanterna de metal prateada e uma caixinha de bijuterias baratas."
  }
}

on use {
  if not has(lanterna) { say "Primeiro pegue a lanterna." }
  else if flag(lanterna_acesa) { say "Já está acesa." }
  else {
    set lanterna_acesa; play "clique de interruptor de lanterna de metal"
    say "Clique. Um facho de luz amarela corta a escuridão."
  }
}

on use {
  if in("Praia Branca") and not flag(nativos_calmos) {
    set nativos_calmos; remove "caixa de bijuterias"
    play "tambores parando, murmúrio de vozes animadas e colares tilintando"
    say "Você abre a caixa e a deixa na areia, aberta, virada para a mata. Por um longo momento, nada. Então mãos rápidas a levam para dentro das folhas, e os tambores param. Uma voz ri. Uma lança é cravada na areia, de ponta para baixo: você pode passar."
  }
  else { say "Ninguém aqui quer bijuterias." }
}

on examine {
  set leu_diario
  say "A última página, com letra apressada: 'A ilha só existe na maré morta. A máquina leva até lá, mas só com o cartão de coordenadas, que guardei no baú do sótão. A passagem para o laboratório fica atrás da estante do porão: é só empurrar a lateral esquerda.'"
}

on push {
  if flag(estante_movida) { say "A passagem já está aberta, a leste." }
  else if flag(leu_diario) {
    set estante_movida; link leste to "Passagem Secreta"; link oeste to "Porão" in "Passagem Secreta"
    play "estante pesada de madeira deslizando sobre piso de cimento"
    say "Você empurra a lateral esquerda. A estante gira sobre um eixo escondido e revela um corredor de pedra, a leste."
  }
  else { say "Ela não se mexe. As marcas no chão dizem que já se moveu muitas vezes; deve haver um jeito certo." }
}
on pull { say "Ela não sai do lugar puxando." }

on pull {
  if flag(energia) { say "Já está ligada." }
  else { set energia; play "alavanca de metal puxada e máquinas elétricas ganhando força, zumbido crescente"; say "Você puxa a alavanca. As luzes piscam, os mostradores sobem e o anel começa a zumbir." }
}
on push { say "Ela está para baixo; teria de puxar." }

on use with "cartão perfurado" {
  if flag(painel_programado) { say "O cartão já está no painel." }
  else { set painel_programado; remove "cartão perfurado"; play "cartão de papel entrando numa leitora mecânica, cliques e bipes"; say "O painel engole o cartão, estala por um tempo e mostra uma linha de números. Coordenadas gravadas." }
}

on use {
  if flag(portal_ativo) { say "O anel está aberto. É só entrar." }
  else if not flag(energia) { say "Nada acontece. A máquina está sem energia." }
  else if not flag(painel_programado) {
    play "descarga elétrica violenta e estrondo de energia"
    end "O anel se acende sem destino nenhum. A luz azul puxa você para dentro e espalha cada pedaço seu entre lugar nenhum e coisa nenhuma. Sem coordenadas, a máquina de Tomás não leva a lugar algum."
  }
  else {
    set portal_ativo; link entrar to "Colina da Chegada"
    play "zumbido elétrico crescendo até um redemoinho de energia se abrir"
    say "O anel acende por dentro: um redemoinho de luz azul, com cheiro de mar. Dá para entrar."
  }
}

scene_54ecade0.ses:
on first_enter {
  say "Você atravessa a luz e cai de joelhos numa trilha quente. O ar é salgado. Não há sinal de casa, nem de ninguém."
}

objects.ses:
on talk {
  if flag(troca_feita) { say "'Negócio é negócio', diz Rocha, alisando o tapete. 'Cuidado com o que mora em tronco oco. E na ilhota, quem chega de mãos vazias não sai.'" }
  else { say "'Aqui ninguém usa dinheiro, forasteiro. Aqui se troca.' Ele olha você de cima a baixo. 'Gente que vem pelo círculo de pedras às vezes traz coisas bonitas do outro lado. Panos bordados, tapetes... Isso sim eu aceito.'" }
}
on use with "tapete persa" {
  if flag(troca_feita) { say "Já negociamos." }
  else {
    set troca_feita; remove "tapete persa"; take "chave de ferro"; take facão; take "luvas de couro"
    play "tapete pesado desenrolado sobre balcão de madeira e moedas tilintando"
    say "Rocha desenrola o tapete sobre o balcão e passa a mão nas franjas de seda, devagar. 'Persa. De verdade.' Ele tira do cinto uma chave de ferro e, de baixo do balcão, um facão e um par de luvas grossas de couro. 'A chave abre o depósito. O facão e as luvas, você vai precisar: a selva daqui não deixa ninguém passar de mãos limpas. Calce as luvas antes de enfiar a mão onde não enxerga.'"
  }
}
on take { say "Rocha segura o seu pulso com uma força que não combina com a idade. 'Aqui se troca. Não se toma.'" }

on use {
  if not has("luvas de couro") { say "Primeiro pegue as luvas." }
  else if flag(luvas_calcadas) { say "Você já está com elas." }
  else { set luvas_calcadas; play "luvas grossas de couro sendo calçadas"; say "Você calça as luvas. O couro é duro e quente, e vai até o meio do braço." }
}

on examine {
  say "Contas do Capitão Rocha, em letra torta. Trocas e mais trocas. Uma das últimas: 'Ao forasteiro de barba castanha: bússola, remo e bomba de ar, em troca de um relógio de bolso. Ficaram no depósito, ele volta para buscar.' Nunca voltou. Mais abaixo: 'Os da ilhota não deixam ninguém passar sem presente. Gostam de coisa que brilha.'"
}

on open {
  if flag(deposito_aberto) { say "Já está aberta. O depósito fica ao norte." }
  else { say "O cadeado de ferro não cede." }
}
on use with "chave de ferro" {
  if flag(deposito_aberto) { say "Já está aberta." }
  else { set deposito_aberto; link norte to "Depósito dos Fundos"; link sul to "Posto do Capitão Rocha" in "Depósito dos Fundos"; play "cadeado de ferro enferrujado abrindo e porta de madeira rangendo"; say "O cadeado abre com um estalo. Você o tira da argola e o deixa no chão. A porta dá para o depósito, ao norte." }
}

on open {
  if flag(bau_capitao_aberto) { say "Já está aberto." }
  else { set bau_capitao_aberto; show bússola; show remo; show "bomba de ar"; play "tampa pesada de baú com ferragens abrindo"; say "A tampa é pesada. Dentro: uma bússola de latão, um remo curto e uma bomba de ar de pé." }
}

on examine {
  if flag(cobra_fugiu) { say "Oco e vazio, só folhas podres." }
  else { say "Coberto de musgo, oco por dentro. Lá no fundo, entre as folhas podres, alguma coisa se mexe e chia baixinho." }
}
on open {
  if flag(cobra_fugiu) { say "Só folhas podres e água. Nada que valha alguma coisa." }
  else {
    if flag(luvas_calcadas) and has("luvas de couro") {
      set cobra_fugiu; play "chiado de cobra e bote rápido entre folhas secas"
      say "Você enfia a mão no oco. Uma pancada seca no pulso: uma jararaca cravou os dentes na luva, mas o couro grosso aguentou. Você puxa o braço com a cobra pendurada; ela se solta, cai na lama e some na água escura. Lá dentro, só folhas podres."
    }
    else {
    play "chiado de cobra e bote rápido entre folhas secas"
    end "Você enfia a mão no oco, entre as folhas podres. Uma picada no pulso, rápida como um estalo. A jararaca some na água escura, e o seu braço começa a queimar. O pântano fica muito longe de qualquer socorro."
    }
  }
}
on use with facão {
  if flag(cobra_fugiu) { say "Não há mais nada lá dentro." }
  else { set cobra_fugiu; play "facão batendo em madeira podre e cobra escorregando na água"; say "Você cutuca o oco com a ponta do facão. Uma jararaca enorme escorrega para fora, sibila para você e some na água escura. Melhor não ter posto a mão." }
}
on use { say "Enfiar a mão aí dentro? Algo se mexe no fundo." }

on examine {
  if flag(bote_cheio) { say "Cheio e firme. Pesado, mas dá para arrastar." }
  else { say "Murcho, mas sem furos. Precisa de ar." }
}
on use with "bomba de ar" {
  if flag(bote_cheio) { say "Já está cheio." }
  else { set bote_cheio; play "bomba de ar de pé bombeando e bote de borracha enchendo"; say "Você bombeia até o braço doer. O bote endurece, mas numa das costuras do fundo a borracha está fina, gasta. Bote velho é assim: uma hora murcha, outra hora vaza." }
}
on push {
  if not flag(bote_cheio) { say "Murcho assim, não vai flutuar." }
  else { set bote_na_praia; hide self; show "bote cinza"; play "bote de borracha sendo arrastado sobre areia"; say "Você arrasta o bote pela trilha, até a beira da água na praia, ao norte." }
}
on pull { say "Melhor empurrar: a trilha para a praia é ao norte." }

on use {
  if not has(balde) { say "Primeiro pegue o balde." }
  else if flag(agua_no_bote) {
    clear agua_no_bote
    play "balde jogando água para fora de um bote de borracha, várias vezes"
    say "Você joga balde atrás de balde por cima da borda até o fundo do bote aparecer de novo. A costura ainda verte, mas agora dá para seguir."
  }
  else { say "Não há nada para esvaziar aqui." }
}

on examine {
  if flag(cipos_cortados) { say "Cortados. Uma passagem estreita leva a leste, até a fenda." }
  else { say "Grossos como braços, emaranhados. Entre eles, um parece mais liso que os outros, com escamas vermelhas, pretas e amarelas." }
}
on use with facão {
  if flag(cipos_cortados) { say "A passagem já está aberta, a leste." }
  else {
    set cipos_cortados; link leste to "Fenda Escura"
    play "facão cortando cipós grossos e galhos caindo"
    say "Você abre caminho a golpes de facão. Um dos cipós se desenrola sozinho e foge rastejando: era uma cobra coral. A passagem para o leste está aberta."
  }
}
on pull {
  if flag(cipos_cortados) { say "Já estão cortados." }
  else {
    play "cobra dando bote e grito abafado na mata"
    end "Você agarra os cipós e puxa com força. Um deles é macio demais, e se mexe. A coral morde a sua mão antes que você possa soltar. Na selva, ninguém ouve você cair."
  }
}
on take {
  if flag(cipos_cortados) { say "Já estão cortados." }
  else {
    play "cobra dando bote e grito abafado na mata"
    end "Você agarra os cipós para arrancá-los. Um deles é macio demais, e se mexe. A coral morde a sua mão antes que você possa soltar. Na selva, ninguém ouve você cair."
  }
}
on push { say "Eles cedem um pouco e voltam, como molas. Sem algo para cortar, não passa." }

scene_13871910.ses:
on enter {
  if not (has(lanterna) and flag(lanterna_acesa)) {
    play "escorregão em pedra molhada e queda no escuro, eco"
    end "Sem luz, você dá dois passos no escuro, pisa no musgo e escorrega para o buraco no meio da fenda. Ninguém nunca vai saber onde você caiu."
  } else {
    say "A luz da lanterna desenha a borda do buraco no meio do chão. Você contorna devagar."
  }
}

objects.ses:
on use with remo {
  if flag(bote_na_agua) { say "O bote já está na água. É só remar para o norte." }
  else {
    set bote_na_agua; link norte to "Mar Aberto"
    play "bote de borracha sendo empurrado para a água, remo batendo no mar"
    say "Você empurra o bote para a água e sobe nele com o remo. O mar aberto fica ao norte."
  }
}
on push { say "Na água, sem remo, ele só ia ficar boiando." }

scene_f222a110.ses:
on enter {
  if flag(agua_no_bote) {
    play "bote de borracha afundando, água borbulhando, ondas"
    end "A praia está ali, a cem metros. Mas o bote já está cheio d'água e afunda de vez, e a arrebentação puxa você para baixo antes da areia."
  }
}

scene_2421e7f8.ses:
on enter {
  if not has(bússola) {
    play "neblina densa, vento uivando e ondas grandes"
    end "Uma névoa branca cai de repente sobre o mar. Sem saber para onde fica o norte, você rema em círculos até as forças acabarem. O bote cinza some na neblina."
  } else {
    set agua_no_bote
    play "água entrando num bote de borracha, borbulhas"
    say "Uma névoa começa a subir do mar, mas a agulha da bússola aponta firme para o norte. Então você sente os pés molhados: uma costura do fundo cedeu, e a água do mar entra no bote, devagar mas sem parar."
  }
}

scene_be680d24.ses:
on enter {
  if flag(agua_no_bote) {
    play "bote de borracha afundando, água borbulhando, gaivotas"
    end "A água já passa dos joelhos. O bote cinza afunda devagar, com você dentro, a poucas braçadas da ilhota. As correntes da maré morta são frias e fundas, e puxam para baixo."
  }
}

objects.ses:
on talk {
  if flag(nativos_calmos) { say "Uma risada na mata. Alguém balança um colar de contas coloridas entre as folhas." }
  else { say "Silêncio. Depois, os tambores, mais rápidos. Uma lança se finca na areia, a um palmo do seu pé, apontando para a mata. Eles querem alguma coisa." }
}
on use with "caixa de bijuterias" {
  set nativos_calmos; remove "caixa de bijuterias"
  play "tambores parando, murmúrio de vozes animadas e colares tilintando"
  say "Você abre a caixa e a deixa na areia, aberta, virada para a mata. Por um longo momento, nada. Então mãos rápidas a levam para dentro das folhas, e os tambores param. Uma voz ri. Uma lança é cravada na areia, de ponta para baixo: você pode passar."
}

on examine {
  if flag(bote_murchou) and not flag(bote_recheio) { say "Murcho. Alguém abriu a válvula. Sem ar, não sai daqui." }
  else { say "O bote cinza, na areia, pronto para voltar ao mar." }
}
on use with "bomba de ar" {
  if not flag(bote_murchou) { say "Está cheio." }
  else if flag(bote_recheio) { say "Já está cheio de novo." }
  else {
    set bote_recheio; link sul to "Mar da Ilhota"
    play "bomba de ar de pé bombeando e bote de borracha enchendo"
    say "Você bombeia com toda a força, de olho na água que sobe. O bote endurece de novo. Para o sul, o mar."
  }
}

scene_91a92135.ses:
on first_enter {
  play "tambores ao longe na mata, ritmo lento e ameaçador"
  say "Você arrasta o bote para a areia. Tambores começam a soar na mata. Entre as folhas, olhos e pontas de lança acompanham cada passo seu. Ninguém aparece. Ninguém precisa."
}
on enter {
  if flag(tomas_resgatado) {
    inc mare
    if flag(mare) > 5 {
      play "ondas fortes engolindo a praia, rugido do mar"
      end "A maré morta acabou. O mar volta de uma vez, alto e rápido, e engole a praia, a trilha e o bote. A ilhota some debaixo d'água, como fazia antes de vocês chegarem. Como fará sempre."
    }
    if not flag(bote_murchou) {
      set bote_murchou; unlink sul
      play "ar escapando de um bote de borracha, risadas na mata"
      say "Na areia, o bote cinza está murcho, mole como um lenço. Da mata vem uma risada abafada: alguém tirou o ar dele enquanto vocês estavam lá dentro. E o mar já começa a subir."
    }
  }
}

scene_43837f94.ses:
on enter {
  if not flag(nativos_calmos) {
    play "lança zunindo no ar e baque surdo"
    end "Você dá as costas para a mata. Os tambores param de repente. O silêncio dura um segundo, e a lança chega antes do som. Quem chega à ilhota de mãos vazias não sai dela."
  }
  if flag(tomas_resgatado) {
    inc mare
    if flag(mare) > 5 {
      play "ondas fortes engolindo a praia, rugido do mar"
      end "A água entra na enseada como um rio. Em minutos, a areia, as rochas e a gruta somem. A maré morta acabou, e a ilhota volta para o fundo do mar com vocês dois."
    }
  }
}

objects.ses:
on use with "carta das marés" {
  if flag(mare_baixa) { say "O caminho ao norte já está aberto." }
  else {
    set mare_baixa; remove "carta das marés"; link norte to "Templo da Maré"
    play "ronco grave de pedra e água recuando, ondas se afastando"
    say "Você deita a carta no sulco. As ondas entalhadas acendem uma a uma, e um ronco vem do chão. Ao norte, a mata se abre: uma trilha de pedras que antes estava debaixo d'água."
  }
}

scene_4508b915.ses:
on enter {
  if not flag(nativos_calmos) {
    play "lança zunindo no ar e baque surdo"
    end "Você entra na mata sem olhar para trás. Os tambores param de repente. O silêncio dura um segundo, e a lança chega antes do som. Quem chega à ilhota de mãos vazias não sai dela."
  }
  if flag(tomas_resgatado) {
    inc mare
    if flag(mare) > 5 {
      play "ondas fortes engolindo a floresta, rugido do mar"
      end "A água sobe pela trilha de pedras e invade a clareira, quente e rápida. A maré morta acabou. A ilhota volta para o fundo do mar com vocês dois."
    }
  }
}

objects.ses:
on open {
  if flag(porta_templo_aberta) { say "Já está aberta. É só entrar." }
  else { say "Não há maçaneta. Só o encaixe redondo no centro." }
}
on use with "medalhão de coral" {
  set porta_templo_aberta; remove "medalhão de coral"
  link norte to "Câmara da Maré"; link entrar to "Câmara da Maré"
  play "porta de pedra pesada se abrindo com estrondo grave"
  say "O medalhão encaixa com um clique. As ondas entalhadas giram, e a porta afunda devagar no chão. Do vão escuro sai uma luz verde e um cheiro de mar parado. Alguém tosse lá dentro."
}

scene_e26bc425.ses:
on enter {
  if flag(tomas_resgatado) {
    inc mare
    if flag(mare) > 5 {
      play "ondas fortes engolindo a floresta, rugido do mar"
      end "A água já cobre os degraus do templo. A maré morta acabou, e a ilhota volta para o fundo do mar com vocês dois."
    }
  }
}

scene_6eee1c1a.ses:
on first_enter {
  set tomas_resgatado
  play "eco de passos em câmara de pedra, voz fraca de homem"
  say "À luz verde das algas, Tomás Albuquerque levanta a cabeça, magro e barbudo, mas vivo. 'A maré me prendeu aqui', ele sussurra. 'Achei que ninguém viria.' Você o ajuda a ficar de pé. 'Rápido. A maré morta está acabando. Quando a água voltar, a ilhota afunda, e nós com ela. E o bote... os da mata adoram brincar com o bote.'"
